/// Reads matching events from `from` up to the head as of the request.
/// Answered by Events frames; the last one carries END and the marker.
#[derive(Debug, Clone, PartialEq)]
pub struct Source<'a> {
    pub context: u16,
    pub from: u64,
    /// Empty matches every event.
    pub criteria: Vec<Criterion<'a>>,
    /// Most events per frame; 0 lets the server choose.
    pub batch_size: u32,
}

impl<'a> Source<'a> {
    pub const KIND: u16 = 0x0101;

    pub fn decode(r: &mut Reader<'a>) -> Result<Self, DecodeError> {
        Ok(Self {
            context: r.u16()?,
            from: r.u64()?,
            criteria: {
                let n0 = r.len16()?;
                let mut v0 = Vec::with_capacity(n0.min(r.remaining()));
                for _ in 0..n0 {
                    v0.push(Criterion::decode(r)?);
                }
                v0
            },
            batch_size: r.u32()?,
        })
    }

    pub fn encode(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {
        let context = &self.context;
        put_u16(w, *context);
        let from = &self.from;
        put_u64(w, *from);
        let criteria = &self.criteria;
        put_len16(w, criteria.len(), "Source.criteria")?;
        for item0 in criteria.iter() {
            item0.encode(w)?;
        }
        let batch_size = &self.batch_size;
        put_u32(w, *batch_size);
        Ok(())
    }

    #[cfg(test)]
    pub fn to_json(&self) -> serde_json::Value {
        #[allow(unused_mut)]
        let mut m = serde_json::Map::new();
        let context = &self.context;
        m.insert("context".into(), serde_json::json!(*context));
        let from = &self.from;
        m.insert("from".into(), serde_json::json!(from.to_string()));
        let criteria = &self.criteria;
        m.insert(
            "criteria".into(),
            serde_json::Value::Array(criteria.iter().map(|item0| item0.to_json()).collect()),
        );
        let batch_size = &self.batch_size;
        m.insert("batch_size".into(), serde_json::json!(*batch_size));
        serde_json::Value::Object(m)
    }
}

