#[derive(Debug, Clone, PartialEq)]
pub struct Query<'a> {
    pub message_id: &'a str,
    pub name: &'a str,
    pub timestamp: i64,
    pub payload: Payload<'a>,
    pub metadata: Vec<MessageMetadata<'a>>,
    pub instructions: Vec<ProcessingInstruction<'a>>,
    pub client_id: &'a str,
    pub component_name: &'a str,
}

impl<'a> Query<'a> {
    pub fn decode(r: &mut Reader<'a>) -> Result<Self, DecodeError> {
        Ok(Self {
            message_id: r.str16()?,
            name: r.str16()?,
            timestamp: r.i64()?,
            payload: Payload::decode(r)?,
            metadata: {
                let n0 = r.len16()?;
                let mut v0 = Vec::with_capacity(n0.min(r.remaining()));
                for _ in 0..n0 {
                    v0.push(MessageMetadata::decode(r)?);
                }
                v0
            },
            instructions: {
                let n0 = r.len16()?;
                let mut v0 = Vec::with_capacity(n0.min(r.remaining()));
                for _ in 0..n0 {
                    v0.push(ProcessingInstruction::decode(r)?);
                }
                v0
            },
            client_id: r.str16()?,
            component_name: r.str16()?,
        })
    }

    pub fn encode(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {
        let message_id = &self.message_id;
        put_str16(w, message_id, "Query.message_id")?;
        let name = &self.name;
        put_str16(w, name, "Query.name")?;
        let timestamp = &self.timestamp;
        put_i64(w, *timestamp);
        let payload = &self.payload;
        payload.encode(w)?;
        let metadata = &self.metadata;
        put_len16(w, metadata.len(), "Query.metadata")?;
        for item0 in metadata.iter() {
            item0.encode(w)?;
        }
        let instructions = &self.instructions;
        put_len16(w, instructions.len(), "Query.instructions")?;
        for item0 in instructions.iter() {
            item0.encode(w)?;
        }
        let client_id = &self.client_id;
        put_str16(w, client_id, "Query.client_id")?;
        let component_name = &self.component_name;
        put_str16(w, component_name, "Query.component_name")?;
        Ok(())
    }

    #[cfg(test)]
    pub fn to_json(&self) -> serde_json::Value {
        #[allow(unused_mut)]
        let mut m = serde_json::Map::new();
        let message_id = &self.message_id;
        m.insert("message_id".into(), serde_json::json!(*message_id));
        let name = &self.name;
        m.insert("name".into(), serde_json::json!(*name));
        let timestamp = &self.timestamp;
        m.insert("timestamp".into(), serde_json::json!(*timestamp));
        let payload = &self.payload;
        m.insert("payload".into(), payload.to_json());
        let metadata = &self.metadata;
        m.insert(
            "metadata".into(),
            serde_json::Value::Array(metadata.iter().map(|item0| item0.to_json()).collect()),
        );
        let instructions = &self.instructions;
        m.insert(
            "instructions".into(),
            serde_json::Value::Array(instructions.iter().map(|item0| item0.to_json()).collect()),
        );
        let client_id = &self.client_id;
        m.insert("client_id".into(), serde_json::json!(*client_id));
        let component_name = &self.component_name;
        m.insert("component_name".into(), serde_json::json!(*component_name));
        serde_json::Value::Object(m)
    }
}

/// One handler's answer to a query. `error_code` is empty on success.
#[derive(Debug, Clone, PartialEq)]
pub struct QueryResult<'a> {
    pub message_id: &'a str,
    pub request_id: &'a str,
    pub error_code: &'a str,
    pub error: Option<ErrorDetail<'a>>,
    pub payload: Option<Payload<'a>>,
    pub metadata: Vec<MessageMetadata<'a>>,
    pub instructions: Vec<ProcessingInstruction<'a>>,
}

impl<'a> QueryResult<'a> {
    pub fn decode(r: &mut Reader<'a>) -> Result<Self, DecodeError> {
        Ok(Self {
            message_id: r.str16()?,
            request_id: r.str16()?,
            error_code: r.str16()?,
            error: if r.present()? {
                Some(ErrorDetail::decode(r)?)
            } else {
                None
            },
            payload: if r.present()? {
                Some(Payload::decode(r)?)
            } else {
                None
            },
            metadata: {
                let n0 = r.len16()?;
                let mut v0 = Vec::with_capacity(n0.min(r.remaining()));
                for _ in 0..n0 {
                    v0.push(MessageMetadata::decode(r)?);
                }
                v0
            },
            instructions: {
                let n0 = r.len16()?;
                let mut v0 = Vec::with_capacity(n0.min(r.remaining()));
                for _ in 0..n0 {
                    v0.push(ProcessingInstruction::decode(r)?);
                }
                v0
            },
        })
    }

    pub fn encode(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {
        let message_id = &self.message_id;
        put_str16(w, message_id, "QueryResult.message_id")?;
        let request_id = &self.request_id;
        put_str16(w, request_id, "QueryResult.request_id")?;
        let error_code = &self.error_code;
        put_str16(w, error_code, "QueryResult.error_code")?;
        let error = &self.error;
        match error {
            Some(some0) => {
                put_u8(w, 1);
                some0.encode(w)?;
            }
            None => put_u8(w, 0),
        }
        let payload = &self.payload;
        match payload {
            Some(some0) => {
                put_u8(w, 1);
                some0.encode(w)?;
            }
            None => put_u8(w, 0),
        }
        let metadata = &self.metadata;
        put_len16(w, metadata.len(), "QueryResult.metadata")?;
        for item0 in metadata.iter() {
            item0.encode(w)?;
        }
        let instructions = &self.instructions;
        put_len16(w, instructions.len(), "QueryResult.instructions")?;
        for item0 in instructions.iter() {
            item0.encode(w)?;
        }
        Ok(())
    }

    #[cfg(test)]
    pub fn to_json(&self) -> serde_json::Value {
        #[allow(unused_mut)]
        let mut m = serde_json::Map::new();
        let message_id = &self.message_id;
        m.insert("message_id".into(), serde_json::json!(*message_id));
        let request_id = &self.request_id;
        m.insert("request_id".into(), serde_json::json!(*request_id));
        let error_code = &self.error_code;
        m.insert("error_code".into(), serde_json::json!(*error_code));
        let error = &self.error;
        m.insert(
            "error".into(),
            match error {
                Some(some0) => some0.to_json(),
                None => serde_json::Value::Null,
            },
        );
        let payload = &self.payload;
        m.insert(
            "payload".into(),
            match payload {
                Some(some0) => some0.to_json(),
                None => serde_json::Value::Null,
            },
        );
        let metadata = &self.metadata;
        m.insert(
            "metadata".into(),
            serde_json::Value::Array(metadata.iter().map(|item0| item0.to_json()).collect()),
        );
        let instructions = &self.instructions;
        m.insert(
            "instructions".into(),
            serde_json::Value::Array(instructions.iter().map(|item0| item0.to_json()).collect()),
        );
        serde_json::Value::Object(m)
    }
}

