/// The follower must drop its log from `position` on. With a boundary, the
/// cut is right after the follower's last event record before `position`,
/// which must be the leader's: `prev_record_crc` is that event record's
/// stored CRC on the leader, or `prev_at_segment_start` says the leader has
/// no event before `position`. Control records are not compared: the follower
/// drops the ones that followed the event and the leader's follow in the
/// bytes that come next.
#[derive(Debug, Clone, PartialEq)]
pub struct TailTruncate {
    pub epoch: u64,
    pub position: u64,
    pub has_boundary: bool,
    pub prev_record_crc: u32,
    pub prev_at_segment_start: bool,
}

impl TailTruncate {
    pub const KIND: u16 = 0x9105;

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        Ok(Self {
            epoch: r.u64()?,
            position: r.u64()?,
            has_boundary: r.bool()?,
            prev_record_crc: r.u32()?,
            prev_at_segment_start: r.bool()?,
        })
    }

    pub fn encode(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {
        let epoch = &self.epoch;
        put_u64(w, *epoch);
        let position = &self.position;
        put_u64(w, *position);
        let has_boundary = &self.has_boundary;
        put_u8(w, *has_boundary as u8);
        let prev_record_crc = &self.prev_record_crc;
        put_u32(w, *prev_record_crc);
        let prev_at_segment_start = &self.prev_at_segment_start;
        put_u8(w, *prev_at_segment_start as u8);
        Ok(())
    }

    #[cfg(test)]
    pub fn to_json(&self) -> serde_json::Value {
        #[allow(unused_mut)]
        let mut m = serde_json::Map::new();
        let epoch = &self.epoch;
        m.insert("epoch".into(), serde_json::json!(epoch.to_string()));
        let position = &self.position;
        m.insert("position".into(), serde_json::json!(position.to_string()));
        let has_boundary = &self.has_boundary;
        m.insert("has_boundary".into(), serde_json::json!(*has_boundary));
        let prev_record_crc = &self.prev_record_crc;
        m.insert(
            "prev_record_crc".into(),
            serde_json::json!(*prev_record_crc),
        );
        let prev_at_segment_start = &self.prev_at_segment_start;
        m.insert(
            "prev_at_segment_start".into(),
            serde_json::json!(*prev_at_segment_start),
        );
        serde_json::Value::Object(m)
    }
}

/// An append a follower received, forwarded to the fenced leader.
#[derive(Debug, Clone, PartialEq)]
pub struct ForwardAppend<'a> {
    pub context: &'a str,
    pub epoch: u64,
    pub leader_id: u64,
    pub system: bool,
    pub condition: Option<Condition<'a>>,
    pub events: Records<'a>,
}

impl<'a> ForwardAppend<'a> {
    pub const KIND: u16 = 0x1102;

    pub fn decode(r: &mut Reader<'a>) -> Result<Self, DecodeError> {
        Ok(Self {
            context: r.str16()?,
            epoch: r.u64()?,
            leader_id: r.u64()?,
            system: r.bool()?,
            condition: if r.present()? {
                Some(Condition::decode(r)?)
            } else {
                None
            },
            events: Records::decode(r)?,
        })
    }

    pub fn encode(&self, w: &mut Vec<u8>) -> Result<(), EncodeError> {
        let context = &self.context;
        put_str16(w, context, "ForwardAppend.context")?;
        let epoch = &self.epoch;
        put_u64(w, *epoch);
        let leader_id = &self.leader_id;
        put_u64(w, *leader_id);
        let system = &self.system;
        put_u8(w, *system as u8);
        let condition = &self.condition;
        match condition {
            Some(some0) => {
                put_u8(w, 1);
                some0.encode(w)?;
            }
            None => put_u8(w, 0),
        }
        let events = &self.events;
        events.encode(w)?;
        Ok(())
    }

    #[cfg(test)]
    pub fn to_json(&self) -> serde_json::Value {
        #[allow(unused_mut)]
        let mut m = serde_json::Map::new();
        let context = &self.context;
        m.insert("context".into(), serde_json::json!(*context));
        let epoch = &self.epoch;
        m.insert("epoch".into(), serde_json::json!(epoch.to_string()));
        let leader_id = &self.leader_id;
        m.insert("leader_id".into(), serde_json::json!(leader_id.to_string()));
        let system = &self.system;
        m.insert("system".into(), serde_json::json!(*system));
        let condition = &self.condition;
        m.insert(
            "condition".into(),
            match condition {
                Some(some0) => some0.to_json(),
                None => serde_json::Value::Null,
            },
        );
        let events = &self.events;
        m.insert("events".into(), events.to_json());
        serde_json::Value::Object(m)
    }
}

